// Card data is generated by ../../export_cards.js from cards.db — don't edit
// cards.json by hand; rerun the export.
import cards from "../data/cards.json";

export interface Card {
  id: number;
  slug: string;
  title: string;
  player: string;
  number: string;
  year: string;
  set: string;
  sport: string;
  team: string;
  condition: string;
  price_cents: number;
  front: string;
  front_sm: string;
  back: string | null;
  back_sm: string | null;
}

export const allCards = cards as Card[];

export const price = (cents: number) => `$${(cents / 100).toFixed(2)}`;

export const heading = (c: Card) => `${c.year} ${c.set} ${c.player} #${c.number}`;

// Same envelope rates as the eBay listings (LISTING_TEMPLATE.md): $1.25 for
// the first card, $0.50 for each additional card.
export const shippingCents = (count: number) => (count > 0 ? 125 + 50 * (count - 1) : 0);

export const byId = new Map(allCards.map((c) => [c.id, c]));
